`timescale 1ns/1ps
module tb_watchdog_soc;
  logic clk=0,rst_n=0,expired,early,tx,halted,fault;
  logic [7:0] leds;
  wire [31:0] count;
  always #5 clk=~clk;
  // This module is generated by GHDL --synth --out=verilog from the VHDL.
  mica_watchdog watchdog(.clk_i(clk),.rst_ni(rst_n),.enable_i(1'b1),.kick_i(1'b0),
    .min_ticks_i(32'd2),.max_ticks_i(32'd500),.expired_o(expired),.early_o(early),.count_o(count));
  mica_soc #(.TRAP(1),.INIT_FILE("program_watchdog.mem32")) dut (
    .clk_i(clk),.rst_ni(rst_n),.uart_rx_i(1'b1),.irq_i(expired),.uart_tx_o(tx),.leds_o(leds),.halted_o(halted),.fault_o(fault));
  initial begin
    repeat(4) @(negedge clk);rst_n=1;
    repeat(3000) begin
      @(negedge clk);
      if(halted) begin
        if(fault || early || !expired || dut.a0!==32'd42) $fatal(1,"watchdog SoC integration");
        $display("GHDL converted VHDL -> SystemVerilog SoC PASS");$finish;
      end
    end
    $fatal(1,"watchdog SoC timeout");
  end
endmodule
